CustomField.formula:
If( OR(
AND(/*###### LIBERA CASO PREÇO APROVADO ######*/ DescontoAprovado__c ,
DivisaoNegocio__r.DivisaoNegocioId__r.Name = "Commodities"),
/*###### ESPECIALIDADE ######*/ AND(DivisaoNegocio__r.DivisaoNegocioId__r.Name = "Especialidades" , DescontoAprovado__c)
/* And( DivisaoNegocio__r.DivisaoNegocioId__r.Name = "Especialidades" ,MaiorDescontovalor__c <= 0.0 ) */ , DivisaoNegocio__r.DivisaoNegocioId__r.Name = "Sucata"
),"Preço aprovado","Preço não aprovado")
